import {liveRecord,poolPlan} from './record-tools.js';
import {provisionLogin,secondaryIdentity} from './admin-tools.js';
import {firebaseConfig,loginDomain} from './config.js';
import {empty,execute,clone,uid,monthKey} from './core.js';
let F,A,db,auth,app,ready;
const keys=['products','users','tasks','returns','losses','adjustments','settlements','audits','syncErrors'];
const TIME0='1970-01-01T00:00:00.000Z',TIMEEND='2100-01-01T00:00:00.000Z';
export async function connect(){if(ready)return ready;ready=(async()=>{const [base,a,f]=await Promise.all([import('https://www.gstatic.com/firebasejs/12.10.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/12.10.0/firebase-auth.js'),import('https://www.gstatic.com/firebasejs/12.10.0/firebase-firestore.js')]);A=a;F=f;app=base.getApps().length?base.getApp():base.initializeApp(firebaseConfig);auth=a.getAuth(app);db=f.getFirestore(app);await auth.authStateReady();})().catch(e=>{ready=null;throw e;});return ready;}
const ref=(k,id)=>F.doc(db,'spark','ops',k,id);const col=k=>F.collection(db,'spark','ops',k);const stamp=iso=>F.Timestamp.fromDate(new Date(iso));
const clean=value=>{if(value?.toDate)return value.toDate().toISOString();if(Array.isArray(value))return value.map(clean);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,clean(v)]));return value;};
async function atomic(fn){return F.runTransaction(db,async tx=>{const revision=await tx.get(ref('meta','revision'));const result=await fn(tx);tx.set(ref('meta','revision'),{value:(revision.data()?.value||0)+1});return result;});}
const safeId=id=>{if(!/^[A-Za-z0-9_.-]{1,60}$/.test(id))throw Error('ID must use letters, numbers, dots, underscores or hyphens.');return id.toLowerCase();};
export async function login(id,password){await connect();const credential=await A.signInWithEmailAndPassword(auth,`${safeId(id)}@${loginDomain}`,password);const member=await F.getDoc(F.doc(db,'members',credential.user.uid));if(!member.exists()||!member.data().active){await A.signOut(auth);throw Error('Account is not enabled. Contact administration.');}return {...member.data(),authUid:credential.user.uid};}
export async function signout(){if(auth)await A.signOut(auth);}
async function docs(k,a){let q=col(k);if(a.role==='packer'&&['tasks','returns','losses','adjustments','payroll','statements','extras'].includes(k))q=F.query(q,F.where('packerId','==',a.id));if(k==='audits')q=F.query(q,F.orderBy('at','desc'),F.limit(200));const snap=await F.getDocs(q);return snap.docs.map(d=>({...clean(d.data()),id:d.id}));}
export async function snapshot(actor){await connect();if(!auth.currentUser)throw Error('Sign in online to refresh this device.');const member=await F.getDoc(F.doc(db,'members',auth.currentUser.uid));if(!member.exists()||!member.data().active||member.data().id!==actor.id)throw Error('Account is no longer enabled.');const start=(await F.getDoc(ref('meta','revision'))).data()?.value||0;const s=empty();s._revision=start;const selected=actor.role==='admin'?[...keys,'accountJobs']:actor.role==='driver'?['products','users','tasks','returns','losses','syncErrors']:['products','users','tasks','returns','losses','adjustments'];await Promise.all(selected.map(async k=>s[k]=await docs(k,actor)));if(actor.role!=='driver'){const prices=await docs('prices',actor),extras=await docs('extras',actor),payroll=await docs('payroll',actor);const rateMap=new Map(prices.map(p=>[p.id,p.rateMicros])),extraMap=new Map(extras.map(p=>[p.id,p.extraMicros]));s.products.forEach(p=>p.rateMicros=rateMap.get(p.rateVersion)||0);s.users.forEach(u=>u.extraMicros=extraMap.get(u.extraVersion)||0);s.tasks.forEach(t=>{t.baseMicros=rateMap.get(t.rateVersion)||0;t.extraMicros=extraMap.get(t.extraVersion)||0;t.rateMicros=t.baseMicros+t.extraMicros;});s.returns.forEach(r=>{const privateLine=payroll.find(p=>p.id===r.id);const task=s.tasks.find(t=>t.id===r.taskId);r.rateMicros=privateLine?.rateMicros??task?.rateMicros??0;r.amountCents=privateLine?.amountCents??Math.round(r.pcs*r.rateMicros/10000);});if(actor.role==='packer')s.settlements=await docs('statements',actor);}
 if(actor.role==='packer'){s.users=s.users.filter(u=>u.id===actor.id);}if(actor.role==='admin'){s._pools=await docs('pools',actor);const personnel=await docs('personnel',actor);s.users.forEach(u=>{const detail=personnel.find(p=>p.id===u.id);if(detail){u.no=detail.no||'';u.ic=detail.ic||'';}});}const end=(await F.getDoc(ref('meta','revision'))).data()?.value||0;if(start!==end)throw Error('Workspace changed during refresh. Retry.');return s;}
function audit(tx,actor,type,id,more={}){tx.set(ref('audits',id),{id,actorId:actor.id,type,at:F.serverTimestamp(),...more});}
function publicTask(t){const x=clone(t);for(const key of ['rateMicros','baseMicros','extraMicros','rateHistory','extraHistory'])delete x[key];return x;}
function publicReturn(r){const x=clone(r);delete x.rateMicros;delete x.amountCents;return x;}
function timestamps(row){const x=clone(row);for(const key of ['occurredAt','uploadedAt','at','confirmedAt','closedAt','reviewedAt'])if(typeof x[key]==='string')x[key]=stamp(x[key]);return x;}
async function deliver(actor,cmd){for(const [i,item] of cmd.payload.items.entries()){const id=`${cmd.id}-${i}`;await atomic(async tx=>{const taskRef=ref('tasks',id);if((await tx.get(taskRef)).exists())return;const [productDoc,userDoc]=await Promise.all([tx.get(ref('products',item.productId)),tx.get(ref('users',cmd.payload.packerId))]);const p=productDoc.data(),u=userDoc.data();if(!p?.active||!p.barcode||!u?.active)throw Error('Unknown product or inactive packer.');if(!Number.isInteger(item.ctn)||item.ctn<1)throw Error('Enter whole cartons.');const poolId=`${u.id}_${p.id}`,poolRef=ref('pools',poolId),poolDoc=await tx.get(poolRef),pool=poolDoc.data();const at=stamp(cmd.payload.occurredAt);if(pool&&pool.lastOccurredAt.toMillis()>at.toMillis()&&!cmd.adminOverride)throw Error('An older offline delivery arrived out of order. Administration must review it.');const task={id,orderId:cmd.id,productId:p.id,productCode:p.code,productName:p.name,packerId:u.id,driverId:cmd.originalDriverId||actor.id,ctn:item.ctn,expected:item.ctn*p.supplierSize/p.rpUnit,supplierSize:p.supplierSize,rpUnit:p.rpUnit,ninsoSize:p.ninsoSize,occurredAt:at,uploadedAt:F.serverTimestamp(),rateVersion:item.rateVersion||p.rateVersion,extraVersion:cmd.payload.extraVersion||u.extraVersion,poolId,receivedPcs:0,approvedLossRaw:0,lastReceiptId:''};let queue=pool?[...pool.queue,id]:[id],head=pool?.head||0;if(cmd.adminOverride&&pool){const priorTasks=await Promise.all(pool.queue.map(id=>tx.get(ref('tasks',id))));const ordered=[...priorTasks.map(d=>d.data()),task].sort((a,b)=>a.occurredAt.toMillis()-b.occurredAt.toMillis()||a.id.localeCompare(b.id));queue=ordered.map(t=>t.id);head=ordered.findIndex(t=>t.ctn*t.supplierSize-t.receivedPcs*t.rpUnit-t.approvedLossRaw>=t.rpUnit);if(head<0)head=queue.length;}tx.set(taskRef,task);tx.set(poolRef,pool?{...pool,queue,head,revision:pool.revision+1,lastDeliveryId:id,lastOccurredAt:pool.lastOccurredAt.toMillis()>at.toMillis()?pool.lastOccurredAt:at}:{id:poolId,queue:[id],head:0,revision:1,lastDeliveryId:id,lastReceiptId:'',lastOccurredAt:at});audit(tx,actor,'deliver',id,{taskId:id});});}}
async function receive(actor,cmd){for(const [i,item] of cmd.payload.items.entries()){let part=0,done=0;const poolId=`${cmd.payload.packerId}_${item.productId}`;while(true){const id=`${cmd.id}-${i}-${part}`;const output=await atomic(async tx=>{const receiptRef=ref('returns',id),previous=await tx.get(receiptRef);if(previous.exists())return {pcs:previous.data().pcs};const poolRef=ref('pools',poolId),poolDoc=await tx.get(poolRef),pool=poolDoc.data();if(!pool||pool.head>=pool.queue.length)throw Error('Quantity exceeds open deliveries. Administration review required.');const taskRef=ref('tasks',pool.queue[pool.head]),taskDoc=await tx.get(taskRef),t=taskDoc.data();if(!t||!liveRecord(t))throw Error('FIFO changed. Refresh or contact administration.');const total=item.ctn*t.ninsoSize+item.loose;if(!Number.isInteger(item.ctn)||item.ctn<0||!Number.isInteger(item.loose)||item.loose<0||item.loose>=t.ninsoSize||total<1)throw Error('Invalid carton or loose quantity.');const left=total-done;if(left<=0)return {pcs:0,finished:true};const raw=t.ctn*t.supplierSize-t.receivedPcs*t.rpUnit-t.approvedLossRaw;const pcs=Math.min(Math.floor(raw/t.rpUnit),left);if(pcs<1)throw Error('FIFO balance requires administration review.');const updated={...t,receivedPcs:t.receivedPcs+pcs,lastReceiptId:id};const rawAfter=raw-pcs*t.rpUnit;const r={id,collectionId:cmd.id,taskId:t.id,poolId,productId:t.productId,productName:t.productName,productCode:t.productCode,packerId:t.packerId,driverId:cmd.originalDriverId||actor.id,pcs,ninsoSize:t.ninsoSize,occurredAt:stamp(cmd.payload.occurredAt),uploadedAt:F.serverTimestamp(),serviceMonth:monthKey(cmd.payload.occurredAt),status:'pending',version:1,settlementId:null};tx.set(receiptRef,r);tx.update(taskRef,updated);tx.update(poolRef,{revision:pool.revision+1,lastReceiptId:id,head:rawAfter<t.rpUnit?pool.head+1:pool.head});audit(tx,actor,'receive',id,{collectionId:cmd.id,taskId:t.id});return {pcs,total};});if(output.finished)return;done+=output.pcs;part++;const s=await snapshot(actor);const t=s.tasks.find(t=>t.productId===item.productId&&t.packerId===cmd.payload.packerId);if(!t)throw Error('Task not found.');if(done>=item.ctn*t.ninsoSize+item.loose)break;}}}
async function confirm(actor,cmd){const id=cmd.payload.id;await atomic(async tx=>{const rRef=ref('returns',id),pRef=ref('payroll',id);const [rDoc,pDoc]=await Promise.all([tx.get(rRef),tx.get(pRef)]);const r=rDoc.data(),draft=pDoc.data();if(!r||r.version!==cmd.payload.version||r.status!=='pending')throw Error('Record changed. Refresh and review again.');const tDoc=await tx.get(ref('tasks',r.taskId)),t=tDoc.data();const [base,extra]=await Promise.all([tx.get(ref('prices',t.rateVersion)),tx.get(ref('extras',t.extraVersion))]);const rate=draft?.rateMicros??base.data().rateMicros+extra.data().extraMicros;const amount=draft?.amountCents??Math.round(r.pcs*rate/10000);tx.update(rRef,{status:'confirmed',confirmedAt:F.serverTimestamp(),confirmedBy:actor.id});tx.set(pRef,{id,packerId:r.packerId,rateMicros:rate,amountCents:amount,status:'confirmed',version:r.version,confirmedAt:F.serverTimestamp()});audit(tx,actor,'confirm',cmd.id,{returnId:id});});}
async function adminCommand(actor,cmd){const state=await snapshot(actor);const after=execute(state,cmd,actor);const revisionRef=ref('meta','revision');const baseline=state._revision;await atomic(async tx=>{const current=await tx.get(revisionRef);if((current.data()?.value||0)!==baseline)throw Error('Workspace changed. Refresh and retry.');const now=new Date().toISOString();let count=0;
 for(const k of keys.filter(k=>!['audits','syncErrors'].includes(k))){const old=new Map((state[k]||[]).map(v=>[v.id,JSON.stringify(v)]));for(const row of after[k]||[])if(old.get(row.id)!==JSON.stringify(row)){let value=clone(row);
 if(k==='products'){const oldProduct=state.products.find(p=>p.id===row.id);const priceId=oldProduct?.rateVersion&&oldProduct.rateMicros===row.rateMicros?oldProduct.rateVersion:`${row.id}-${cmd.id}`;if(priceId!==oldProduct?.rateVersion){if(oldProduct?.rateVersion)tx.update(ref('prices',oldProduct.rateVersion),{endsAt:stamp(now)});tx.set(ref('prices',priceId),{id:priceId,productId:row.id,rateMicros:row.rateMicros,startsAt:stamp(oldProduct?now:TIME0),endsAt:stamp(TIMEEND)});}value.rateVersion=priceId;delete value.rateMicros;delete value.rateHistory;}
 if(k==='users'){tx.set(ref('personnel',row.id),{id:row.id,no:row.no||'',ic:row.ic||''});delete value.ic;delete value.no;delete value.password;if(row.authUid)tx.set(F.doc(db,'members',row.authUid),{id:row.id,name:row.name,shortName:row.shortName||'',role:row.role,active:row.active});const oldUser=state.users.find(u=>u.id===row.id);const extraId=oldUser?.extraVersion&&oldUser.extraMicros===row.extraMicros?oldUser.extraVersion:`${row.id}-${cmd.id}`;if(extraId!==oldUser?.extraVersion){if(oldUser?.extraVersion)tx.update(ref('extras',oldUser.extraVersion),{endsAt:stamp(now)});tx.set(ref('extras',extraId),{id:extraId,packerId:row.id,extraMicros:row.extraMicros,startsAt:stamp(oldUser?now:TIME0),endsAt:stamp(TIMEEND)});}value.extraVersion=extraId;delete value.extraMicros;delete value.extraHistory;}
 if(k==='tasks')value=publicTask(value);
 if(k==='returns'){value=publicReturn(value);tx.set(ref('payroll',row.id),{id:row.id,packerId:row.packerId,rateMicros:row.rateMicros,amountCents:row.amountCents,status:row.status,version:row.version});}
 tx.set(ref(k,row.id),timestamps(value));count++;
 if(k==='settlements'){for(const packerId of new Set(row.lines.map(l=>l.packerId))){const lines=row.lines.filter(l=>l.packerId===packerId);tx.set(ref('statements',`${row.id}_${packerId}`),{...row,packerId,lines,totalCents:lines.reduce((n,l)=>n+l.amountCents,0)});}}
 }}
 // Reconcile public quantity ledgers after administrative corrections and approved losses.
 for(const t of after.tasks){const received=after.returns.filter(r=>r.taskId===t.id&&liveRecord(r)).reduce((n,r)=>n+r.pcs,0)+after.adjustments.filter(a=>a.taskId===t.id&&a.status==='confirmed').reduce((n,a)=>n+a.pcs,0);const loss=after.losses.filter(l=>l.taskId===t.id&&l.status==='approved').reduce((n,l)=>n+l.rawQty,0);if(t.receivedPcs!==received||t.approvedLossRaw!==loss)tx.update(ref('tasks',t.id),{receivedPcs:received,approvedLossRaw:loss});}
 for(const p of state.products){if(!after.products.some(v=>v.id===p.id)){tx.delete(ref('products',p.id));count++;}}
 for(const pool of state._pools||[]){const plan=poolPlan(pool,after);if(pool.head!==plan.head||JSON.stringify(pool.queue)!==JSON.stringify(plan.queue))tx.update(ref('pools',pool.id),{...plan,revision:pool.revision+1});}

if(count>150)throw Error('Split this change into smaller batches.');tx.set(revisionRef,{value:baseline+1});const last=after.audits.at(-1);audit(tx,actor,cmd.type,cmd.id,{...last,at:F.serverTimestamp()});});}
export async function dispatch(actor,cmd){await connect();if(cmd.type==='deliver')return deliver(actor,cmd);if(cmd.type==='receive')return receive(actor,cmd);if(cmd.type==='confirm')return confirm(actor,cmd);if(cmd.type==='dispute'){await atomic(async tx=>{const r=ref('returns',cmd.payload.id);const d=await tx.get(r);if(d.data()?.version!==cmd.payload.version)throw Error('Record changed.');tx.update(r,{status:'disputed',dispute:cmd.payload.note});audit(tx,actor,'dispute',cmd.id,{returnId:cmd.payload.id});});return;}if(cmd.type==='loss'){const t=(await F.getDoc(ref('tasks',cmd.payload.taskId))).data();const x=cmd.payload;await atomic(async tx=>{if((await tx.get(ref('losses',cmd.id))).exists())return;tx.set(ref('losses',cmd.id),{id:cmd.id,...x,rawQty:x.qty*(x.unit==='raw'?1:t.rpUnit),packerId:t.packerId,driverId:actor.id,status:'pending',at:F.serverTimestamp()});audit(tx,actor,'loss',cmd.id);});return;}if(actor.role==='admin')return adminCommand(actor,cmd);if(cmd.type==='confirmAdjustment'){await atomic(async tx=>{const r=ref('adjustments',cmd.payload.id),d=await tx.get(r);const a=d.data();if(!a||a.packerId!==actor.id||a.status!=='pending'||a.version!==cmd.payload.version)throw Error('Adjustment changed.');const taskRef=ref('tasks',a.taskId),td=await tx.get(taskRef),task=td.data();const poolRef=ref('pools',task.poolId),pd=await tx.get(poolRef),pool=pd.data();const received=task.receivedPcs+a.pcs,raw=task.ctn*task.supplierSize-received*task.rpUnit-task.approvedLossRaw;if(received<0||raw<0)throw Error('Adjustment conflicts with later collections. Contact administration.');const index=pool.queue.indexOf(task.id);let head=pool.head;if(index<head&&raw>=task.rpUnit)head=index;else if(index===head&&raw<task.rpUnit)head++;tx.update(taskRef,{receivedPcs:received,lastAdjustmentId:a.id});tx.update(poolRef,{head,revision:pool.revision+1,lastAdjustmentId:a.id});tx.update(r,{status:'confirmed',confirmedAt:F.serverTimestamp()});audit(tx,actor,'confirmAdjustment',cmd.id,{adjustmentId:a.id});});return;}throw Error('Permission denied.');}
export async function reportIssue(actor,cmd,error){try{await F.setDoc(ref('syncErrors',cmd.id),{id:cmd.id,cmd,driverId:actor.id,actorId:actor.id,packerId:cmd.payload.packerId||'',status:'pending',error:String(error).slice(0,1000),at:F.serverTimestamp()});}catch{}}
export async function accountAction(actor,x){await connect();if(actor.role!=='admin')throw Error('Administration only.');if(x.action==='reveal')throw Error('Stored passwords cannot be viewed.');if(x.action==='reset'){const id=uid();await F.setDoc(ref('accountJobs',id),{id,type:'reset',targetId:x.id,status:'pending',requestedBy:actor.id,at:F.serverTimestamp()});return {queued:true};}if(x.action==='save'){if(x.password)throw Error('Passwords are set by the PC account manager. Import the account CSV there.');await adminCommand(actor,{id:uid(),type:'saveUser',payload:x.person});return {ok:true};}throw Error('Unsupported account action.');}

// Dependency injection for Emulator Suite integration tests; authorization remains in Firestore Rules.
export function configureTestRuntime(sdk,database,uid){F=sdk;db=database;auth={currentUser:{uid}};ready=Promise.resolve();}

export async function issueResolution(id){await connect();const d=await F.getDoc(ref('syncErrors',id));return d.data()?.status;}
export async function resolveIssue(actor,data){await connect();if(actor.role!=='admin'||!data.note?.trim())throw Error('Administration reason required.');const docRef=ref('syncErrors',data.id),d=await F.getDoc(docRef),issue=d.data();if(!issue||issue.status!=='pending')throw Error('Issue already resolved.');if(!data.reject)await dispatch(actor,{...issue.cmd,payload:data.payload,adminOverride:true,originalDriverId:issue.driverId});await F.updateDoc(docRef,{status:data.reject?'rejected':'corrected',note:data.note,resolvedBy:actor.id,resolvedAt:F.serverTimestamp()});await F.setDoc(ref('audits',uid()),{actorId:actor.id,type:'resolveSync',submissionId:data.id,reason:data.note,original:issue.cmd.payload,corrected:data.reject?null:data.payload,at:F.serverTimestamp()});}
export async function watch(actor,onChange){await connect();return F.onSnapshot(ref('meta','revision'),()=>onChange(),()=>{});}
export async function provisionAccount(actor,id,password,options={}){
 await connect();
 const primaryUid=auth.currentUser?.uid;
 const personDoc=await F.getDoc(ref('users',id));
 if(!personDoc.exists())throw Error('Save the personnel profile first.');
 const person={...personDoc.data(),id};
 const authorize=async()=>{
  if(!primaryUid||actor?.role!=='admin')throw Error('Active administrator required.');
  const member=await F.getDoc(F.doc(db,'members',primaryUid));
  if(!member.exists()||member.data().role!=='admin'||!member.data().active||member.data().id!==actor.id)throw Error('Active administrator required.');
 };
 if((options.skipExisting||options.preserveLinked)&&person.authUid){await authorize();const linked=await F.getDoc(F.doc(db,'members',person.authUid));const m=linked.data();if(!linked.exists()||m.id!==id||m.role!==person.role||m.active!==person.active){const error=Error('Linked member record needs repair.');error.code='account/link-missing';throw error;}return {skipped:true,created:false,reason:'Profile already linked',verifiedLinked:true};}
 return provisionLogin({actor,person,password,...options},{
  authorize:async()=>{
   if(!primaryUid)throw Error('Sign in as administration first.');
   const member=await F.getDoc(F.doc(db,'members',primaryUid));
   if(!member.exists()||member.data().role!=='admin'||!member.data().active||member.data().id!==actor.id)throw Error('Active administrator required.');
  },
  identity:async(loginId,secret,identityOptions)=>{
   const base=await import('https://www.gstatic.com/firebasejs/12.10.0/firebase-app.js');
   return secondaryIdentity({base,sdk:A,config:firebaseConfig,domain:loginDomain,id:loginId,password:secret,name:'provision-'+uid(),...identityOptions});
  },
  link:async(admin,profile,authUid)=>{
   if(auth.currentUser?.uid!==primaryUid)throw Error('Administrator session changed.');
   await atomic(async tx=>{
    const userRef=ref('users',profile.id),memberRef=F.doc(db,'members',authUid),adminRef=F.doc(db,'members',primaryUid);
    const [current,target,administrator]=await Promise.all([tx.get(userRef),tx.get(memberRef),tx.get(adminRef)]);
    const p=current.data(),a=administrator.data();
    if(!p?.active||p.role!==profile.role||a?.role!=='admin'||!a.active||a.id!==admin.id)throw Error('Personnel or administrator status changed.');
    if((p.authUid&&p.authUid!==authUid)||(target.exists()&&target.data().id!==profile.id))throw Error('Login already linked to another person.');
    tx.update(userRef,{authUid});
    tx.set(memberRef,{id:profile.id,name:p.name,shortName:p.shortName||'',role:p.role,active:p.active});
    audit(tx,admin,'linkLogin',uid(),{targetId:profile.id,authUid});
   });
  }
 });
}
